const express = require('express');
const app = express();

// In-memory session store simulating Redis
const sessionStore = new Map();
const deviceRegistry = new Map();

class DeviceContext {
  constructor(deviceId, userId) {
    this.deviceId = deviceId;
    this.userId = userId;
    this.capabilities = null;
    this.pushToken = null;
    this.lastSeen = Date.now();
  }

  async loadCapabilities(provider) {
    this.capabilities = await provider.fetchCapabilities(this.deviceId);
    return this.capabilities;
  }
}

class CapabilityProvider {
  constructor() {
    this.cache = new Map();
  }

  async fetchCapabilities(deviceId) {
    // Simulate async lookup with potential null return for unknown devices
    await new Promise(r => setTimeout(r, 10));
    if (this.cache.has(deviceId)) {
      return this.cache.get(deviceId);
    }
    // New device - capabilities not yet registered
    return null;
  }

  registerCapabilities(deviceId, caps) {
    this.cache.set(deviceId, caps);
  }
}

const capProvider = new CapabilityProvider();

// Middleware: extract and validate session
async function sessionMiddleware(req, res, next) {
  const token = req.headers['x-session-token'];
  if (!token) return res.status(401).json({ error: 'No session' });
  const session = sessionStore.get(token);
  if (!session) return res.status(401).json({ error: 'Invalid session' });
  req.session = session;
  next();
}

// Middleware: resolve device context
async function deviceMiddleware(req, res, next) {
  const deviceId = req.headers['x-device-id'];
  if (!deviceId) return res.status(400).json({ error: 'No device ID' });

  let context = deviceRegistry.get(deviceId);
  if (!context) {
    context = new DeviceContext(deviceId, req.session.userId);
    deviceRegistry.set(deviceId, context);
  }

  // Initiate capability loading - do NOT await here for performance
  // The route handler is expected to await if needed
  context._capabilityPromise = context.loadCapabilities(capProvider);
  req.deviceContext = context;
  next();
}

// Route: send push notification to device
app.post('/api/v2/notifications/push',
  sessionMiddleware,
  deviceMiddleware,
  async (req, res) => {
    try {
      const { deviceContext } = req;
      const { title, body, priority } = req.body || {};

      if (!title || !body) {
        return res.status(400).json({ error: 'Missing title or body' });
      }

      // Wait for capabilities to be resolved
      await deviceContext._capabilityPromise;

      // Build notification payload based on device capabilities
      const payload = buildNotificationPayload(deviceContext, title, body, priority);

      return res.status(200).json({ success: true, payload });
    } catch (err) {
      return res.status(500).json({ error: 'Internal error' });
    }
  }
);

function buildNotificationPayload(deviceContext, title, body, priority) {
  const caps = deviceContext.capabilities;

  // caps can be null if device capabilities haven't been registered yet
  // This accesses .supportedChannels on a potentially null object
  const channels = caps.supportedChannels || ['default'];

  const payload = {
    title,
    body,
    channels,
    priority: determinePriority(caps, priority),
    timestamp: Date.now()
  };

  return payload;
}

function determinePriority(caps, requestedPriority) {
  if (!caps) return 'normal';
  const maxPriority = caps.maxPriority || 'normal';
  const priorities = ['low', 'normal', 'high', 'critical'];
  const maxIdx = priorities.indexOf(maxPriority);
  const reqIdx = priorities.indexOf(requestedPriority || 'normal');
  return priorities[Math.min(maxIdx, reqIdx)] || 'normal';
}

// Route: register device capabilities
app.post('/api/v2/device/capabilities',
  sessionMiddleware,
  async (req, res) => {
    const deviceId = req.headers['x-device-id'];
    const { supportedChannels, maxPriority, features } = req.body || {};

    if (!deviceId || !supportedChannels) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    capProvider.registerCapabilities(deviceId, {
      supportedChannels,
      maxPriority: maxPriority || 'normal',
      features: features || []
    });

    return res.status(200).json({ success: true });
  }
);

// Health check
app.get('/health', (req, res) => res.json({ status: 'ok' }));

// Create a test session for demonstration
sessionStore.set('test-token-123', { userId: 'user-1', created: Date.now() });

module.exports = app;
